import React from "react";
import {
  Box, Typography, Button,
} from "@mui/material";
import Grid from "./components/Grid";
import { ZB_COLORS } from "./theme";

const podcastEpisodes = [
  { id: 1, title: "The Rise of Zambian Tech", guest: "Chipo Mwansa", description: "Chipo shares her journey from student to CTO of a Lusaka-based startup.", audioUrl: "" },
  { id: 2, title: "Finance in Africa", guest: "John Banda", description: "John discusses the future of finance and fintech in Zambia and beyond.", audioUrl: "" },
  { id: 3, title: "Breaking into Procurement", guest: "Mule Tembo", description: "A practical guide to starting a career in procurement and supply chain.", audioUrl: "" },
];

export function Podcast() {
  return (
    <Box sx={{ maxWidth: 860, mx: "auto", px: { xs: 2, md: 4 }, py: { xs: 4, md: 6 } }}>
      <Typography sx={{ fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: ZB_COLORS.gold, fontWeight: 600, mb: 1, fontFamily: "DM Sans" }}>Listen</Typography>
      <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>Making of an Industry Giant</Typography>
      <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 4 }}>
        Conversations with Zambia's top professionals, entrepreneurs, and innovators.
      </Typography>

      {podcastEpisodes.map(ep => (
        <Box key={ep.id} sx={{ background: ZB_COLORS.navyMid, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "12px", p: 3, mb: 2, display: "flex", gap: 3, alignItems: "flex-start", flexWrap: "wrap" }}>
          <Box sx={{ width: 56, height: 56, borderRadius: "12px", background: "rgba(255,214,0,0.12)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "1.5rem", flexShrink: 0 }}>
            🎙️
          </Box>
          <Box sx={{ flexGrow: 1, minWidth: 200 }}>
            <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", mb: 0.25 }}>Ep. {ep.id} — {ep.title}</Typography>
            <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.gold, fontFamily: "DM Sans", mb: 0.75 }}>Guest: {ep.guest}</Typography>
            <Typography sx={{ fontSize: "0.875rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 2 }}>{ep.description}</Typography>
            {ep.audioUrl ? (
              <audio controls src={ep.audioUrl} style={{ width: "100%", filter: "invert(0.8)" }} />
            ) : (
              <Box sx={{ background: ZB_COLORS.cardBg, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "8px", p: 1.5, fontSize: "0.8rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>
                Episode coming soon — subscribe to be notified.
              </Box>
            )}
          </Box>
        </Box>
      ))}
    </Box>
  );
}

export function Contact() {
  return (
    <Box sx={{ maxWidth: 640, mx: "auto", px: { xs: 2, md: 4 }, py: { xs: 4, md: 8 }, textAlign: "center" }}>
      <Typography sx={{ fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: ZB_COLORS.gold, fontWeight: 600, mb: 1, fontFamily: "DM Sans" }}>Get in touch</Typography>
      <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>Contact us</Typography>
      <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 4 }}>We'd love to hear from you. Reach out via any of these channels.</Typography>

      <Grid container spacing={2} justifyContent="center">
        {[
          { label: "Email", value: "info@zbridge.com", href: "mailto:info@zbridge.com", icon: "✉️" },
          { label: "Phone", value: "+260 97 000 0000", href: "tel:+260970000000", icon: "📞" },
          { label: "LinkedIn", value: "Z-Bridge Zambia", href: "https://linkedin.com", icon: "💼" },
        ].map(c => (
          <Grid item xs={12} sm={4} key={c.label}>
            <Box sx={{ background: ZB_COLORS.navyMid, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "12px", p: 2.5, textAlign: "center" }}>
              <Box sx={{ fontSize: "1.5rem", mb: 1 }}>{c.icon}</Box>
              <Typography sx={{ fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.06em", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 0.5 }}>{c.label}</Typography>
              <Box component="a" href={c.href} target="_blank" rel="noopener noreferrer" sx={{ color: ZB_COLORS.gold, fontFamily: "DM Sans", fontSize: "0.875rem", textDecoration: "none", "&:hover": { textDecoration: "underline" } }}>
                {c.value}
              </Box>
            </Box>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
}

export function PrivacyPolicy() {
  const sections = [
    { title: "What we collect", body: "We collect basic profile information you voluntarily provide such as your name, profession, academic background, and selected interests. We do not collect sensitive personal data without explicit consent." },
    { title: "How we use your data", body: "Your information is used solely to personalise your ZBRIDGE experience — to recommend relevant simulations, resources, and mentors. We do not sell or share your data with third parties." },
    { title: "Data storage", body: "Data is stored securely using Firebase infrastructure. We apply industry-standard security practices to protect your information." },
    { title: "Your rights", body: "You can request deletion of your account and associated data at any time by contacting us at info@zbridge.com." },
    { title: "Contact", body: "If you have any questions about this privacy policy, reach out to info@zbridge.com." },
  ];

  return (
    <Box sx={{ maxWidth: 760, mx: "auto", px: { xs: 2, md: 4 }, py: { xs: 4, md: 6 } }}>
      <Typography sx={{ fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: ZB_COLORS.gold, fontWeight: 600, mb: 1, fontFamily: "DM Sans" }}>Legal</Typography>
      <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>Privacy Policy</Typography>
      <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 4 }}>Last updated: January 2025</Typography>
      {sections.map(s => (
        <Box key={s.title} sx={{ mb: 3 }}>
          <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", mb: 1 }}>{s.title}</Typography>
          <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", lineHeight: 1.7 }}>{s.body}</Typography>
        </Box>
      ))}
    </Box>
  );
}

export default Podcast;
